(function () {
// Holztrattner VL 7 (Mängelhaftung II): neue Fälle, je 6 Antworten, mit Lösungsweg
const W=(window.WPRK_LONG=window.WPRK_LONG||[]);
const L=[{"topic": "kauf", "sv": "Studentin S kauft beim Elektronikhändler E einen neuen Saugroboter für 480 €. Nach drei Wochen bleibt der Roller ständig stehen. E holt das Gerät ab, tauscht die Hauptplatine und gibt es zurück. Zwei Tage später bleibt der Roboter wieder ständig stehen. S erklärt sofort den Rücktritt. E meint, ihm stünden „wie jedem Verkäufer zwei Versuche“ zu, S müsse ihm erst eine neue Frist setzen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Der Rücktritt ist unwirksam, weil die Nacherfüllung erst nach dem zweiten erfolglosen Versuch als fehlgeschlagen gilt (§ 440 S. 2).", "Falsch. § 440 ist beim Verbrauchsgüterkauf nicht anwendbar; § 475d I verdrängt ihn als abschließende Sonderregel."], ["Der Rücktritt ist unwirksam, weil S nach dem ersten Fehlschlag eine neue angemessene Frist hätte setzen müssen (§ 323 I).", "Falsch. Beim Verbrauchsgüterkauf ist die Fristsetzung entbehrlich, wenn sich trotz versuchter Nacherfüllung ein Mangel zeigt (§ 475d I Nr. 2)."], ["Der Rücktritt ist wirksam, aber nur, weil E die Nacherfüllung ernsthaft und endgültig verweigert hat (§ 323 II Nr. 1).", "Falsch. E hat nicht verweigert, sondern erfolglos repariert. § 323 II ist beim Verbrauchsgüterkauf ohnehin nicht anwendbar."], ["Der Rücktritt ist wirksam: Beim Verbrauchsgüterkauf genügt schon ein erfolgloser Nacherfüllungsversuch (§ 475d I Nr. 2).", "Richtig. Zeigt sich trotz versuchter Nacherfüllung ein Mangel, kann der Verbraucher ohne weitere Frist zurücktreten; der Mangel ist erheblich."], ["Der Rücktritt ist unwirksam, weil S als Verbraucherin zunächst eine Minderung hätte erklären müssen (§ 441 I).", "Falsch. Rücktritt und Minderung stehen zur Wahl („statt zurückzutreten“). Eine Reihenfolge gibt es nicht."], ["Der Rücktritt ist wirksam, aber S muss E für die Zeit der Nutzung den vollen Kaufpreis als Nutzungsersatz zahlen (§ 346 I).", "Falsch. Nutzungsersatz bemisst sich nach dem tatsächlichen Gebrauchsvorteil (anteilig), nicht nach dem vollen Kaufpreis."]], "id": "P6-vl7-0", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Die Bäckerei B GmbH kauft beim Fachhändler F einen Profi-Backofen für 14.000 €. Die Temperaturregelung ist von Anfang an defekt. B setzt eine Frist zur Nachbesserung. F tauscht innerhalb der Frist den Temperaturfühler, doch der Ofen heizt weiter ungleichmäßig. B erklärt sofort den Rücktritt, ohne F eine weitere Gelegenheit zu geben. F verweist auf sein Recht zu einem zweiten Versuch.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Der Rücktritt ist unwirksam, weil die Nachbesserung zwischen Unternehmern in der Regel erst nach dem zweiten erfolglosen Versuch als fehlgeschlagen gilt (§ 440 S. 2).", "Richtig. Außerhalb des Verbrauchsgüterkaufs gilt § 440: Nach einem Fehlschlag muss der Käufer dem Verkäufer grundsätzlich einen weiteren Versuch ermöglichen."], ["Der Rücktritt ist wirksam, weil sich trotz versuchter Nacherfüllung ein Mangel zeigt und dann keine weitere Frist nötig ist (§ 475d I Nr. 2).", "Falsch. § 475d gilt nur beim Verbrauchsgüterkauf. B ist eine GmbH, also Unternehmerin."], ["Der Rücktritt ist wirksam, weil die von B gesetzte Frist mit dem misslungenen Versuch abgelaufen und verbraucht ist (§ 323 I).", "Falsch. F hat innerhalb der Frist nachgebessert. Ob die Nacherfüllung fehlgeschlagen ist, richtet sich nach § 440 S. 2."], ["Der Rücktritt ist unwirksam, weil ein Rücktritt zwischen Unternehmern nur bei Verschulden des Verkäufers möglich ist (§ 280 I).", "Falsch. Der Rücktritt ist immer verschuldensunabhängig. Verschulden braucht man nur für Schadensersatz."], ["Der Rücktritt ist wirksam, weil ein Mangel an einer neuen Sache die Nacherfüllung stets unzumutbar macht (§ 440 S. 1 Var. 3).", "Falsch. Unzumutbar ist die Nacherfüllung nur bei besonderen Umständen (z. B. Arglist). „Stets“ ist falsch."], ["Der Rücktritt ist unwirksam, weil B den Mangel nicht nach § 377 HGB gerügt hat.", "Falsch. B hat den Mangel durch die Fristsetzung gerügt. Der Rücktritt scheitert am fehlenden zweiten Versuch."]], "id": "P6-vl7-1", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucher V kauft beim Fahrradhändler H ein neues Lastenrad. Die Gangschaltung springt ständig heraus. V meldet den Mangel. H antwortet: „Da bin ich gerade nicht zuständig, wenden Sie sich doch an den Hersteller.“ V erklärt daraufhin den Rücktritt, ohne eine Frist zu setzen. H meint, er habe die Nacherfüllung nicht „ernsthaft und endgültig“ verweigert.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Der Rücktritt ist unwirksam, weil eine Frist nur bei ernsthafter und endgültiger Verweigerung entbehrlich ist (§ 323 II Nr. 1).", "Falsch. § 323 II gilt beim Verbrauchsgüterkauf nicht. § 475d I Nr. 4 lässt schon die einfache Verweigerung genügen."], ["Der Rücktritt ist unwirksam, weil V sich zunächst an den Hersteller wenden muss, wenn der Händler das verlangt.", "Falsch. Mängelrechte bestehen gegen den Vertragspartner H. Einen Vorrang des Herstellers gibt es nicht."], ["Der Rücktritt ist wirksam, weil eine Gangschaltung, die herausspringt, stets ein so schwerer Mangel ist, dass sofort zurückgetreten werden darf (§ 475d I Nr. 3).", "Falsch. Ein Schaltungsdefekt ist ärgerlich, aber regelmäßig nicht „derart schwerwiegend“. Entscheidend ist hier die Verweigerung."], ["Der Rücktritt ist unwirksam, weil V die Nacherfüllung ausdrücklich verlangen und eine Frist von mindestens zwei Wochen abwarten muss (§ 475 V).", "Falsch. Die Frist des § 475d I Nr. 1 ist nur eine von mehreren Alternativen. Bei einer Verweigerung (Nr. 4) braucht es sie nicht."], ["Der Rücktritt ist wirksam, weil beim Verbrauchsgüterkauf schon die einfache Verweigerung der Nacherfüllung genügt (§ 475d I Nr. 4).", "Richtig. H hat die Nacherfüllung abgelehnt und V an den Hersteller verwiesen. Beim Verbrauchsgüterkauf muss die Weigerung nicht ernsthaft und endgültig sein."], ["Der Rücktritt ist wirksam, aber nur, wenn H die Verweigerung schriftlich erklärt hat (§ 126).", "Falsch. Für die Verweigerung gibt es keine Form. Eine mündliche Ablehnung reicht."]], "id": "P6-vl7-2", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "K kauft beim Händler V einen gebrauchten Konzertflügel für 9.000 €. Mangelfrei wäre der Flügel 12.000 € wert. Wegen eines Risses im Resonanzboden, den V trotz Frist nicht behebt, ist er tatsächlich nur 8.000 € wert. K erklärt die Minderung und hat den vollen Kaufpreis bereits bezahlt.", "q": "Wie viel kann K von V zurückverlangen?", "c": 2, "o": [["1.000 €, weil der Flügel 1.000 € weniger wert ist als der Kaufpreis (9.000 € − 8.000 €).", "Falsch. Die Minderung wird nicht als Differenz zum Kaufpreis berechnet, sondern verhältnismäßig nach § 441 III."], ["4.000 €, weil der Flügel durch den Mangel 4.000 € an Wert verloren hat (12.000 € − 8.000 €).", "Falsch. Das wäre die Wertdifferenz. Der Käufer bekommt aber nur den Anteil seines Kaufpreises, der dem Wertverlust entspricht."], ["3.000 €: Der Preis sinkt auf 9.000 € × 8.000/12.000 = 6.000 € (§ 441 III, IV).", "Richtig. Herabgesetzt wird im Verhältnis von mangelhaftem zu mangelfreiem Wert. Das zu viel Gezahlte erstattet V nach § 441 IV."], ["6.000 €, weil sich nach der Formel des § 441 III ein Minderungsbetrag von 6.000 € ergibt.", "Falsch. Die Formel ergibt den geminderten Kaufpreis (6.000 €), nicht den Erstattungsbetrag. Zurück gibt es die Differenz zum gezahlten Preis."], ["Nichts, weil K einen gebrauchten Flügel gekauft hat und bei gebrauchten Sachen keine Minderung möglich ist.", "Falsch. Auch beim Kauf gebrauchter Sachen bestehen alle Mängelrechte, soweit sie nicht wirksam ausgeschlossen sind."], ["2.250 €, weil der Preis um den Anteil des Wertverlusts am Kaufpreis (4.000/12.000 = 25 %) gekürzt wird.", "Falsch. 4.000 von 12.000 sind ein Drittel, nicht 25 %. Ein Drittel von 9.000 € ergibt 3.000 €."]], "id": "P6-vl7-3", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Unternehmerin U kauft beim Händler H einen Firmenwagen. Wegen eines Defekts an der Klimaanlage erklärt sie nach erfolgloser Frist die Minderung um 1.500 €. Drei Wochen später fällt die Klimaanlage ganz aus; U möchte den Wagen nun doch zurückgeben und erklärt den Rücktritt. Neue Mängel sind nicht hinzugekommen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Der Rücktritt ist wirksam, weil die Minderung bis zur Zahlung des Minderungsbetrags jederzeit widerrufen werden kann (§ 441 IV).", "Falsch. § 441 IV regelt nur die Erstattung des zu viel Gezahlten. Ein Widerrufsrecht für die Minderung gibt es nicht."], ["Der Rücktritt ist wirksam, weil Rücktritt und Minderung nebeneinander bestehen und der Käufer frei zwischen ihnen wechseln kann.", "Falsch. Die Minderung wird „statt zurückzutreten“ erklärt (§ 441 I 1). Beide Rechte schließen sich aus."], ["Der Rücktritt ist wirksam, weil sich der Mangel inzwischen verschlimmert hat und damit eine neue Wahl eröffnet ist.", "Falsch. Es handelt sich um denselben Mangel. Nur ein neuer Mangel könnte neue Rechte auslösen."], ["Der Rücktritt ist unwirksam, weil Unternehmer nur mindern, nicht zurücktreten können (§ 474).", "Falsch. Rücktritt und Minderung stehen jedem Käufer zu. § 474 regelt nur den Verbrauchsgüterkauf."], ["Der Rücktritt ist unwirksam, aber U kann stattdessen noch großen Schadensersatz verlangen und so den Wagen zurückgeben (§ 281 V).", "Falsch. Nach dem BGH ist der Käufer auch an einem Wechsel zum großen Schadensersatz gehindert, wenn er wirksam gemindert hat. Möglich bleibt nur kleiner Schadensersatz."], ["Der Rücktritt ist unwirksam, weil U mit der Minderung ihr Wahlrecht endgültig ausgeübt hat (§ 441 I).", "Richtig. Die Minderung hat den Vertrag endgültig umgestaltet. U kann wegen desselben Mangels nicht mehr zurücktreten."]], "id": "P6-vl7-4", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Grafikdesigner G kauft beim Händler H einen neuen Monitor für 1.200 € für sein Büro. Am Bildrand zeigt sich ein schmaler Streifen mit leicht abweichender Farbe; der Minderwert beträgt 60 €. H hätte den Fehler bei der Endkontrolle in seiner eigenen Werkstatt bemerken müssen, verweigert aber jede Nacherfüllung. G will den Monitor zurückgeben und von H die Mehrkosten von 150 € für ein teureres Ersatzmodell.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["G kann den Monitor zurückgeben und 150 € verlangen, weil H die Nacherfüllung verweigert hat und deshalb jeder Schadensersatz offensteht (§ 281 II).", "Falsch. Die Verweigerung macht nur die Frist entbehrlich. Den großen Schadensersatz sperrt § 281 I 3 bei unerheblichen Mängeln."], ["G kann nur kleinen Schadensersatz verlangen: Er behält den Monitor und bekommt 60 € (§§ 280 I, III, 281 I 3).", "Richtig. Bei unerheblichem Mangel ist Schadensersatz statt der ganzen Leistung ausgeschlossen. Der kleine Schadensersatz – der Minderwert – bleibt möglich."], ["G hat keine Rechte, weil ein Minderwert von 5 % beim Neugerät noch kein Sachmangel ist (§ 434).", "Falsch. Jede Abweichung von der geschuldeten Beschaffenheit ist ein Mangel. Die Erheblichkeit spielt erst bei Rücktritt und großem Schadensersatz eine Rolle."], ["G kann zurücktreten, weil ein Rücktritt bei Verweigerung der Nacherfüllung auch bei geringfügigen Mängeln möglich ist (§ 323 II Nr. 1).", "Falsch. § 323 V 2 schließt den Rücktritt bei unerheblicher Pflichtverletzung immer aus, auch nach einer Verweigerung."], ["G kann den Monitor zurückgeben und 150 € verlangen, muss H aber eine Frist von zwei Wochen setzen (§ 281 I 1).", "Falsch. Die Frist wäre nach der Verweigerung entbehrlich (§ 281 II). Am Ausschluss des großen Schadensersatzes ändert eine Frist nichts."], ["G kann den Kaufpreis um 60 € mindern, aber keinen Schadensersatz verlangen, weil H den Mangel nicht verursacht hat.", "Falsch. Für den Schadensersatz kommt es auf das Vertretenmüssen an; H hätte den Fehler bei der eigenen Endkontrolle erkennen müssen. Minderung wäre ebenfalls möglich, aber nicht nur sie."]], "id": "P6-vl7-5", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "K kauft vom Händler V einen gebrauchten Oldtimer für 18.000 €. Bei Übergabe hat der Wagen einen nicht mehr reparierbaren Rahmenschaden, der seinen Wert um 6.000 € mindert. K hat erst 5.000 € angezahlt. Er behält das Auto, erklärt weder Rücktritt noch Minderung und weigert sich, den Rest zu zahlen: Da die Nacherfüllung unmöglich sei, sei er nach § 326 I 1 „automatisch“ von seiner Zahlungspflicht frei.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K hat Recht: Ist die Nacherfüllung unmöglich, entfällt der Anspruch auf die Gegenleistung kraft Gesetzes (§ 326 I 1).", "Falsch. § 326 I 2 macht genau für diesen Fall eine Ausnahme: Bei Unmöglichkeit der Nacherfüllung wird der Käufer nicht automatisch frei."], ["K muss nur 7.000 € zahlen, weil die Minderung bei Unmöglichkeit automatisch eintritt (§ 441 III).", "Falsch. Die Minderung wirkt nur durch Erklärung (§ 441 I). Zudem wird sie verhältnismäßig berechnet, nicht durch Abzug der Wertminderung."], ["K muss nichts mehr zahlen, weil V ihm einen mangelhaften Wagen geliefert und damit seine Hauptpflicht verletzt hat (§ 320).", "Falsch. § 320 gibt nur ein Zurückbehaltungsrecht, solange Nacherfüllung möglich ist. Bei unmöglicher Nacherfüllung läuft es leer."], ["K bleibt zur Zahlung von 13.000 € verpflichtet, solange er nicht zurücktritt oder mindert (§ 326 I 2).", "Richtig. Bei Unmöglichkeit der Nacherfüllung gilt § 326 I 1 nicht. K muss sich für ein Mängelrecht entscheiden; bis dahin bleibt der Kaufpreis geschuldet."], ["K muss 13.000 € zahlen und hat keinerlei Mängelrechte mehr, weil er den Wagen trotz des Schadens behalten hat (§ 442).", "Falsch. § 442 betrifft die Kenntnis bei Vertragsschluss. Das Behalten der Sache schließt Rücktritt oder Minderung nicht aus."], ["K muss 13.000 € zahlen, kann aber nur Schadensersatz verlangen, weil Rücktritt bei unbehebbaren Mängeln ausgeschlossen ist (§ 326 V).", "Falsch. Gerade umgekehrt: § 326 V eröffnet bei unbehebbarem Mangel den Rücktritt ohne Fristsetzung."]], "id": "P6-vl7-6", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Autohändler A kauft einen Gebrauchtwagen von einem Privatmann, der ihm schriftlich versichert, das Fahrzeug sei unfallfrei. A lässt den Wagen von einer Werkstatt durchsehen, die nichts findet, und verkauft ihn an die Unternehmerin U als „unfallfrei“ für 21.000 €. Später stellt sich heraus, dass der Wagen schon vor dem Verkauf an A einen fachgerecht reparierten schweren Unfall hatte, der auch bei sorgfältiger Prüfung nicht erkennbar war. U erklärt sofort den Rücktritt und verlangt zusätzlich 1.200 € entgangenen Gewinn.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["U kann nicht zurücktreten, weil sie A zuerst eine Frist zur Nacherfüllung setzen muss (§ 323 I).", "Falsch. Die Unfalleigenschaft lässt sich nicht beseitigen; die Nacherfüllung ist unmöglich. Dann ist die Frist entbehrlich (§ 326 V)."], ["U kann zurücktreten und Schadensersatz verlangen, weil A für die Angaben seines Vorbesitzers einstehen muss (§§ 278, 311a II).", "Falsch. Der private Vorbesitzer ist nicht A's Erfüllungsgehilfe gegenüber U. A selbst kannte den Mangel nicht und musste ihn nicht kennen."], ["U kann ohne Frist zurücktreten, aber keinen Schadensersatz verlangen, weil A den Unfall weder kannte noch kennen musste (§§ 326 V, 311a II 2).", "Richtig. Rücktritt ist verschuldensunabhängig; Schadensersatz bei anfänglich unbehebbarem Mangel entfällt, wenn der Verkäufer das Leistungshindernis nicht kannte und nicht kennen musste."], ["U kann keinen Rücktritt erklären, weil ein fachgerecht reparierter Unfall bei einem Gebrauchtwagen kein Mangel ist (§ 434 III).", "Falsch. Vereinbart war „unfallfrei“. Ein Unfallwagen weicht von der vereinbarten Beschaffenheit ab, auch wenn er gut repariert ist (§ 434 II 1 Nr. 1)."], ["U kann nur den Kaufvertrag wegen arglistiger Täuschung anfechten, weil A „unfallfrei“ zugesagt hat (§ 123 I).", "Falsch. A hat nicht arglistig gehandelt, er wusste nichts vom Unfall. Es bleiben die Mängelrechte."], ["U kann zurücktreten und 1.200 € verlangen, weil der Verkäufer für Angaben ins Blaue hinein stets ohne Verschulden haftet (§ 276 I).", "Falsch. A hat nicht ins Blaue hinein behauptet, sondern sich auf eine Erklärung des Vorbesitzers und eine Werkstattprüfung gestützt."]], "id": "P6-vl7-7", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Der Verein V kauft beim Händler H für seine Vereinsfeier eine Musikanlage für 3.000 €. Im Vertrauen auf die Lieferung bezahlt V eine Bühne mit Elektroanschluss (400 €), die nur für diese Anlage gebaut wurde. Die Anlage brummt so laut, dass sie unbrauchbar ist; H hatte den Mangel beim Probelauf in seinem Laden bemerkt und trotzdem ausgeliefert. Trotz Frist bessert H nicht nach. V tritt zurück und verlangt außerdem die 400 € für die nutzlos gewordene Bühne.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["V kann die 400 € nicht verlangen, weil der Rücktritt Ersatzansprüche ausschließt (§ 349).", "Falsch. Rücktritt und Schadensersatz bzw. Aufwendungsersatz schließen sich nicht aus (§ 325)."], ["V kann die 400 € nur verlangen, wenn er nachweist, dass die Anlage ihm mindestens 3.400 € Gewinn gebracht hätte.", "Falsch. Für den Aufwendungsersatz nach § 284 kommt es nicht auf Gewinne an. Gerade deshalb gibt es ihn, z. B. bei ideellen Zwecken wie einer Vereinsfeier."], ["V kann die 400 € verlangen, und zwar verschuldensunabhängig, weil die Aufwendungen wegen des Mangels nutzlos wurden (§ 284).", "Falsch. § 284 setzt voraus, dass die Voraussetzungen des Schadensersatzes statt der Leistung vorliegen – also auch Vertretenmüssen."], ["V kann die 400 € nicht verlangen, weil Aufwendungen für Bühnen keine Folge des Kaufvertrags sind, sondern eigene Entscheidungen des Käufers.", "Falsch. V hat die Bühne gerade im Vertrauen auf den Erhalt der Anlage gebaut. Das sind typische vergebliche Aufwendungen."], ["V kann die 400 € nur als Teil der Minderung zurückverlangen, weil der Kaufpreis um die nutzlosen Kosten sinkt (§ 441).", "Falsch. Minderung betrifft nur den Kaufpreis. Zudem hat V den Rücktritt erklärt; daneben passt keine Minderung."], ["V kann zurücktreten und daneben die 400 € als vergebliche Aufwendungen ersetzt verlangen (§§ 284, 325).", "Richtig. Die Voraussetzungen des Schadensersatzes statt der Leistung liegen vor (Frist, Vertretenmüssen). Statt Schaden kann V die im Vertrauen auf die Leistung gemachten Aufwendungen verlangen."]], "id": "P6-vl7-8", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Im Möbelhaus M sieht die Verbraucherin V an einem neuen Esstisch einen deutlichen Kratzer. Sie kauft den Tisch trotzdem zum vollen Preis, ohne dass über den Kratzer gesprochen oder etwas dazu vereinbart wird. Zu Hause verlangt sie Nacherfüllung. M meint, wer einen Mangel beim Kauf kenne, habe keine Rechte.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["V hat Mängelrechte, weil § 442 beim Verbrauchsgüterkauf nicht gilt und keine Vereinbarung nach § 476 I 2 vorliegt (§ 475 III 2).", "Richtig. Beim Verbrauchsgüterkauf schließt bloße Kenntnis die Rechte nicht aus. Nötig wäre ein eigener Hinweis und eine ausdrückliche, gesonderte Vereinbarung der Abweichung."], ["V hat keine Mängelrechte, weil sie den Mangel bei Vertragsschluss kannte (§ 442 I 1).", "Falsch. So wäre es zwischen Unternehmern oder Privatleuten. Beim Verbrauchsgüterkauf ist § 442 nach § 475 III 2 nicht anzuwenden."], ["V hat Mängelrechte, aber nur, wenn M den Kratzer arglistig verschwiegen hat (§ 442 I 2).", "Falsch. Die Arglist-Ausnahme betrifft die grob fahrlässige Unkenntnis außerhalb des Verbrauchsgüterkaufs. Hier gilt § 442 gar nicht."], ["V hat keine Mängelrechte, weil ein sichtbarer Kratzer eine stillschweigende negative Beschaffenheitsvereinbarung ist (§ 434 II).", "Falsch. Beim Verbrauchsgüterkauf genügt eine stillschweigende Vereinbarung nicht. § 476 I 2 verlangt einen eigenen Hinweis und eine ausdrückliche, gesonderte Vereinbarung."], ["V hat Mängelrechte, kann aber nur mindern, weil sie den Mangel gekannt hat und Nacherfüllung deshalb unbillig wäre.", "Falsch. Eine solche Beschränkung kennt das Gesetz nicht. V hat alle Rechte des § 437, zuerst die Nacherfüllung."], ["V hat keine Mängelrechte, weil ein Kratzer an einem Tisch die Gebrauchstauglichkeit nicht beeinträchtigt und damit unerheblich ist.", "Falsch. Auch optische Mängel sind Sachmängel. Die Erheblichkeit spielt nur für Rücktritt und großen Schadensersatz eine Rolle, nicht für die Nacherfüllung."]], "id": "P6-vl7-9", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H ein neues E-Bike. Im handschriftlich ausgehandelten Kaufvertrag (keine AGB) steht: „Wegen des Sonderpreises sind Rücktritt, Minderung und Schadensersatz ausgeschlossen; Nachbesserung bleibt möglich.“ Später fällt der Akku wiederholt aus; die Nachbesserung schlägt fehl. K will zurücktreten und Ersatz der Taxikosten von 40 €, die durch einen Ausfall entstanden sind. H hat den Fehler weder gekannt noch arglistig verschwiegen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Beide Ausschlüsse sind wirksam, weil Rücktritt und Schadensersatz individuell und nicht durch AGB ausgeschlossen wurden.", "Falsch. Beim Verbrauchsgüterkauf ist ein Ausschluss von Rücktritt und Minderung auch individualvertraglich unwirksam (§ 476 I)."], ["Beide Ausschlüsse sind unwirksam, weil beim Verbrauchsgüterkauf keinerlei Einschränkung der Mängelrechte möglich ist (§ 476 I).", "Falsch. § 476 III nimmt den Schadensersatz ausdrücklich aus. Er kann – unter Beachtung der §§ 307–309 und des § 444 – ausgeschlossen werden."], ["Der Ausschluss ist insgesamt wirksam, weil K einen Sonderpreis erhalten hat und damit kompensiert ist (§ 242).", "Falsch. Ein Preisnachlass rechtfertigt keine Abweichung von § 476 I. Die Vorschrift ist zwingend."], ["Der Ausschluss des Rücktritts ist wirksam, der des Schadensersatzes unwirksam, weil Schadensersatz zum Kern des Verbraucherschutzes gehört.", "Falsch. Genau umgekehrt: Rücktritt und Minderung sind zwingend, Schadensersatz kann nach § 476 III ausgeschlossen werden."], ["K kann zurücktreten, aber die 40 € nicht verlangen, weil nur der Schadensersatz wirksam ausgeschlossen ist (§ 476 I, III).", "Richtig. Der Ausschluss von Rücktritt und Minderung ist unwirksam. Der Ausschluss des Schadensersatzes ist individuell vereinbart, und § 444 greift nicht."], ["K kann nur mindern, weil Rücktritt nach einem Sonderpreis unverhältnismäßig wäre (§ 323 V 2).", "Falsch. § 323 V 2 stellt auf die Erheblichkeit des Mangels ab, nicht auf den Preis. Ein Akku, der wiederholt ausfällt, ist ein erheblicher Mangel."]], "id": "P6-vl7-10", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Die Möbelfabrik M GmbH kauft beim Holzgroßhändler H 400 Eichenplatten. Im Rahmenvertrag beider Kaufleute heißt es: „Die Untersuchungs- und Rügeobliegenheit nach § 377 HGB wird abbedungen; Mängelrechte bleiben bis zur gesetzlichen Verjährung erhalten.“ M lagert die Platten zunächst ein und entdeckt erst nach vier Monaten bei der Verarbeitung, dass ein Drittel Risse hat, die bei einer Stichprobe sofort aufgefallen wären. M verlangt Nachlieferung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["M hat keine Rechte, weil sie den offensichtlichen Mangel nicht unverzüglich gerügt hat und die Ware deshalb als genehmigt gilt (§ 377 II HGB).", "Falsch. Das wäre ohne die Vereinbarung richtig. § 377 HGB ist aber dispositiv und wurde hier wirksam abbedungen."], ["M kann Nachlieferung verlangen, weil die Parteien die Rügeobliegenheit wirksam abbedungen haben (§§ 437 Nr. 1, 439 I).", "Richtig. § 377 HGB ist dispositiv und kann vertraglich ausgeschlossen werden (laut Skript auch über AGB). Die Genehmigungsfiktion greift deshalb nicht."], ["M hat keine Rechte, weil § 377 HGB zwingendes Handelsrecht ist und nicht abbedungen werden kann.", "Falsch. Laut Skript ist § 377 II HGB dispositiv. Die Parteien können die Rügeobliegenheit vertraglich ausschließen."], ["M kann Nachlieferung verlangen, aber nur für die Platten, die sie bis zum Ablauf von zwei Wochen nach Lieferung untersucht hätte.", "Falsch. Eine solche Zwei-Wochen-Grenze gibt es nicht. Nach Abbedingung gilt allein die gesetzliche Verjährung des § 438."], ["M kann nur mindern, weil sie die Platten vier Monate gelagert hat und Nachlieferung deshalb unverhältnismäßig ist (§ 439 IV).", "Falsch. Die Lagerzeit macht eine Nachlieferung von Platten nicht unverhältnismäßig. M hat zudem ein Wahlrecht."], ["M hat keine Rechte, weil Mängelrechte zwischen Kaufleuten nach drei Monaten verjähren.", "Falsch. Auch zwischen Kaufleuten gilt die zweijährige Verjährung des § 438 I Nr. 3, sofern nichts anderes vereinbart ist."]], "id": "P6-vl7-11", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Gastwirt G, im Handelsregister eingetragener Kaufmann, kauft für sein Restaurant vom Privatmann P dessen gebrauchte Kühltruhe, die P bei einer Haushaltsauflösung nicht mehr braucht. G schließt die Truhe erst nach sechs Wochen an und stellt fest, dass sie nicht kühlt. P meint, G habe als Kaufmann sofort untersuchen und rügen müssen; jetzt sei es zu spät.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["P hat Recht, weil der Käufer als Kaufmann stets unverzüglich untersuchen und rügen muss (§ 377 I HGB).", "Falsch. § 377 HGB verlangt einen beiderseitigen Handelskauf. P ist kein Kaufmann."], ["P hat Recht, weil § 377 HGB auch gilt, wenn nur der Käufer Kaufmann ist und das Geschäft zu seinem Handelsgewerbe gehört (§ 345 HGB).", "Falsch. § 345 HGB gilt für viele einseitige Handelsgeschäfte, § 377 HGB aber verlangt ausdrücklich ein Geschäft, das für beide Teile ein Handelsgeschäft ist."], ["G hat keine Rechte, weil Privatleute beim Verkauf gebrauchter Sachen nie haften.", "Falsch. Auch Privatverkäufer haften für Mängel, solange die Gewährleistung nicht wirksam ausgeschlossen ist."], ["G behält seine Mängelrechte, weil § 377 HGB nur beim beiderseitigen Handelskauf gilt (§ 343 HGB).", "Richtig. P handelt privat, für ihn ist der Kauf kein Handelsgeschäft. Ohne beiderseitigen Handelskauf gibt es keine Rügeobliegenheit."], ["G behält seine Mängelrechte, aber nur, weil er die Truhe noch nicht benutzt hat (§ 377 III HGB).", "Falsch. Ergebnis richtig, Begründung falsch: § 377 HGB ist hier gar nicht anwendbar. Auf die Nutzung kommt es nicht an."], ["G hat nur Ansprüche aus Garantie, weil Privatverkäufer bei gebrauchten Sachen nur aus Garantie haften (§ 443).", "Falsch. Eine Garantie hat P nicht gegeben. G hat die gesetzlichen Mängelrechte aus § 437."]], "id": "P6-vl7-12", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Gebrauchtwagenhändler G einen fünf Jahre alten Kleinwagen. In den AGB auf der Rückseite des Vertrags steht unter Ziffer 12: „Ansprüche wegen Sachmängeln verjähren in einem Jahr ab Ablieferung.“ Auf die Klausel wird V weder hingewiesen, noch wird sie gesondert vereinbart. Nach 16 Monaten zeigt sich ein Getriebeschaden, der schon bei Übergabe angelegt war. G beruft sich auf Verjährung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Der Anspruch ist verjährt, weil die Verjährung bei gebrauchten Sachen auch im Verbrauchsgüterkauf auf ein Jahr verkürzt werden kann (§ 476 II).", "Falsch. § 476 II erlaubt die Verkürzung zwar, aber nur unter seinen besonderen Voraussetzungen. Eine bloße AGB-Klausel genügt nicht."], ["Der Anspruch ist verjährt, weil bei Gebrauchtwagen die gesetzliche Verjährung ohnehin nur ein Jahr beträgt (§ 438 I Nr. 3).", "Falsch. § 438 I Nr. 3 sieht zwei Jahre vor – gleich ob neu oder gebraucht. Ein Jahr gilt nur bei wirksamer Verkürzung."], ["Der Anspruch ist nicht verjährt, weil beim Verbrauchsgüterkauf jede Verkürzung der Verjährung unwirksam ist (§ 476 I).", "Falsch. „Jede“ ist zu weit: Bei gebrauchten Sachen ist eine Verkürzung auf ein Jahr möglich, wenn die Anforderungen des § 476 II erfüllt sind."], ["Der Anspruch ist verjährt, weil V die AGB unterschrieben hat und damit die Klausel ausdrücklich vereinbart wurde (§ 305 II).", "Falsch. Die Einbeziehung als AGB ist keine „ausdrückliche und gesonderte“ Vereinbarung im Sinne des § 476 II."], ["Der Anspruch ist nicht verjährt, weil die Beweislastumkehr nach einem Jahr ausläuft und V den Mangel nun beweisen muss (§ 477).", "Falsch. § 477 betrifft die Beweislast, nicht die Verjährung. Die Beweisfrage ändert nichts daran, ob der Anspruch verjährt ist."], ["Nicht verjährt: Die Verkürzung ist mangels Hinweis und gesonderter Vereinbarung unwirksam (§ 476 II).", "Richtig. Es bleibt bei zwei Jahren ab Ablieferung (§ 438 I Nr. 3, II). Nach 16 Monaten ist der Anspruch nicht verjährt."]], "id": "P6-vl7-13", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Privatmann P verkauft dem Privatmann K sein Motorrad. Im Vertrag steht: „Verkauf unter Ausschluss jeder Gewährleistung. Der Verkäufer garantiert, dass der Motor nicht getauscht wurde.“ P glaubt das selbst, weil er das Motorrad so gekauft hat. Tatsächlich hatte ein Vorbesitzer den Motor getauscht; das Motorrad ist dadurch 1.500 € weniger wert. K verlangt 1.500 € Schadensersatz.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K hat keinen Anspruch, weil der Gewährleistungsausschluss unter Privatleuten uneingeschränkt wirksam ist (§ 476 gilt nicht).", "Falsch. § 476 gilt zwar nicht, wohl aber § 444: Soweit der Verkäufer eine Garantie übernommen hat, kann er sich auf den Ausschluss nicht berufen."], ["K hat keinen Anspruch, weil P den Motortausch nicht kannte und deshalb nicht schuldhaft gehandelt hat (§ 280 I 2).", "Falsch. Wer eine Beschaffenheit garantiert, haftet auch ohne Verschulden (§ 276 I 1: „Übernahme einer Garantie“)."], ["K kann 1.500 € verlangen, weil P die Beschaffenheit garantiert hat (§§ 444, 276 I 1).", "Richtig. Die Beschaffenheitsgarantie sperrt den Haftungsausschluss und begründet eine verschuldensunabhängige Einstandspflicht. Der Mangel ist nicht behebbar → Schadensersatz nach § 311a II."], ["K kann 1.500 € verlangen, aber nur, wenn P arglistig gehandelt hat, weil § 444 nur Arglist erfasst.", "Falsch. § 444 nennt zwei Fälle: arglistiges Verschweigen und Übernahme einer Garantie für die Beschaffenheit."], ["K kann nur zurücktreten, weil Schadensersatz bei Privatverkäufen generell ausgeschlossen werden kann (§ 476 III).", "Falsch. § 476 III betrifft den Verbrauchsgüterkauf. Für Privatverkäufe gilt § 444, und der greift hier wegen der Garantie."], ["K kann 1.500 € nur vom Vorbesitzer verlangen, weil dieser den Motor getauscht hat.", "Falsch. K hat keinen Vertrag mit dem Vorbesitzer. Ansprüche hat er gegen seinen Verkäufer P."]], "id": "P6-vl7-14", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucher V kauft beim Händler H eine Kaffeemaschine; Ablieferung am 10. März 2024. Am 1. November 2025 tritt erstmals ein Pumpendefekt auf. V meldet ihn sofort, H repariert und gibt die Maschine am 25. Februar 2026 zurück. Am 20. April 2026 zeigt sich derselbe Defekt wieder. V verlangt erneut Nacherfüllung; H beruft sich auf Verjährung, weil zwei Jahre seit der Ablieferung vergangen seien.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Der Anspruch ist verjährt, weil die zwei Jahre ab Ablieferung am 10. März 2026 abgelaufen sind (§ 438 I Nr. 3, II).", "Falsch. Beim Verbrauchsgüterkauf greifen die Ablaufhemmungen des § 475e. Die Verjährung trat deshalb nicht am 10. März ein."], ["Nicht verjährt: Wegen der Reparatur tritt die Verjährung nicht vor dem 25. April 2026 ein (§ 475e IV).", "Richtig. Wurde ein Mangel innerhalb der Frist geltend gemacht und nachgebessert, tritt die Verjährung nicht vor Ablauf von zwei Monaten nach Übergabe der nachgebesserten Ware ein."], ["Der Anspruch ist verjährt, weil die Hemmung um vier Monate nach dem ersten Auftreten schon am 1. März 2026 endete (§ 475e III).", "Falsch. § 475e III wirkt zwar nur bis 1. März 2026. Daneben gilt aber § 475e IV mit der späteren Frist bis 25. April 2026."], ["Der Anspruch ist nicht verjährt, weil mit jeder Reparatur eine neue zweijährige Verjährungsfrist beginnt (§ 212 I Nr. 1).", "Falsch. „Mit jeder Reparatur“ ist zu pauschal: Ein Neubeginn nach § 212 I Nr. 1 tritt nur ein, wenn die Reparatur im Einzelfall als Anerkenntnis zu werten ist. Sicher greift hier die Ablaufhemmung des § 475e IV."], ["Nicht verjährt, weil nach einer Reparatur wieder auftretende Mängel nie verjähren.", "Falsch. Auch solche Ansprüche verjähren. § 475e IV schiebt das Ende nur um zwei Monate nach Rückgabe hinaus."], ["Der Anspruch ist verjährt, weil V nach der Reparatur sofort hätte prüfen und den Mangel innerhalb von zwei Wochen rügen müssen (§ 377 HGB).", "Falsch. § 377 HGB gilt nur beim beiderseitigen Handelskauf. V ist Verbraucher."]], "id": "P6-vl7-15", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Händler H ein Auto-Navigationsgerät; Ablieferung am 1. Juni 2024. Laut Vertrag erhält sie drei Jahre lang (bis 31. Mai 2027) aktuelle Verkehrsdaten per Funk. Ab Juli 2027 – also nach Ablauf der zwei Jahre ab Ablieferung – stellt V fest, dass die Verkehrsdaten schon seit März 2027 fehlerhaft übertragen wurden. Sie macht im August 2027 Mängelrechte geltend. H beruft sich auf Verjährung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Der Anspruch ist verjährt, weil Mängelansprüche zwei Jahre ab Ablieferung verjähren, hier also am 1. Juni 2026 (§ 438 I Nr. 3).", "Falsch. Für dauerhaft bereitgestellte digitale Elemente gilt die Sonderregel des § 475e I, die das Ende hinausschiebt."], ["Der Anspruch ist verjährt, weil die Verkehrsdaten kein Teil der Ware sind und deshalb nur Ansprüche aus §§ 327 ff. bestehen, die schon verjährt sind.", "Falsch. Verkehrsdaten im Navi sind das Skript-Beispiel für eine Ware mit dauerhaft bereitgestellten digitalen Elementen (§ 475c)."], ["Der Anspruch ist nicht verjährt, weil die Verjährung erst mit Entdeckung des Mangels im Juli 2027 beginnt (§ 199 I).", "Falsch. § 199 I betrifft die Regelverjährung. Mängelansprüche richten sich nach § 438 und hier nach § 475e I."], ["Der Anspruch ist nicht verjährt, weil die Gewährleistung bei digitalen Elementen nie verjährt, solange das Gerät genutzt wird.", "Falsch. Auch hier gibt es eine Verjährung. § 475e I verlängert sie nur bis zwölf Monate nach Ende des Bereitstellungszeitraums."], ["Nicht verjährt: Bei dauerhafter Bereitstellung tritt die Verjährung nicht vor dem 31. Mai 2028 ein (§ 475e I).", "Richtig. Bei dauerhafter Bereitstellung digitaler Elemente läuft die Verjährung nicht vor Ablauf von zwölf Monaten nach Ende des Bereitstellungszeitraums ab."], ["Der Anspruch ist nicht verjährt, aber V kann nur noch mindern, weil Nacherfüllung bei digitalen Elementen ausgeschlossen ist.", "Falsch. Nacherfüllung (z. B. durch Bereitstellung fehlerfreier Daten) ist möglich und vorrangig."]], "id": "P6-vl7-16", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "K kauft beim Elektronikmarkt E einen Kühlschrank. Der Hersteller H legt eine „5-Jahres-Garantie auf den Kompressor“ bei: „Fällt der Kompressor innerhalb von fünf Jahren aus, tauschen wir ihn kostenlos.“ Nach drei Jahren fällt der Kompressor durch normalen Verschleiß aus. E lehnt ab, die Gewährleistung sei abgelaufen. K fragt, an wen er sich halten kann.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["K kann von H den Austausch aus der Garantie verlangen; gegenüber E sind die Mängelrechte verjährt (§§ 443, 438 I Nr. 3).", "Richtig. Die Herstellergarantie ist ein selbständiger Garantievertrag neben der gesetzlichen Gewährleistung. Sie richtet sich gegen H und deckt hier auch Verschleiß innerhalb der Garantiezeit."], ["K kann von E Nacherfüllung verlangen, weil die Herstellergarantie die Gewährleistungsfrist des Händlers auf fünf Jahre verlängert.", "Falsch. Die Garantie eines Dritten ändert nichts an den gesetzlichen Rechten gegen den Verkäufer. Diese verjähren nach zwei Jahren (§ 438 I Nr. 3)."], ["K hat keinen Anspruch, weil Verschleiß nie unter eine Garantie fällt, sondern nur Mängel bei Übergabe.", "Falsch. Der Inhalt einer Garantie richtet sich nach der Garantieerklärung. Eine Haltbarkeitsgarantie kann gerade auch Ausfälle während der Laufzeit erfassen."], ["K kann von H den Austausch nur verlangen, wenn er beweist, dass H den Defekt verschuldet hat.", "Falsch. Ansprüche aus einer Garantie setzen kein Verschulden voraus."], ["K hat keinen Anspruch gegen H, weil er mit H keinen Kaufvertrag geschlossen hat und Garantien nur zwischen Kaufvertragsparteien wirken.", "Falsch. Eine Herstellergarantie ist ein eigener Vertrag zwischen Hersteller und Käufer (selbständiger Garantievertrag)."], ["K kann wahlweise von E oder H Austausch verlangen, weil beide gesamtschuldnerisch für die Garantie haften (§ 421).", "Falsch. Garantiegeber ist nur H. E hat keine eigene Garantie übernommen und haftet nur aus der (verjährten) Gewährleistung."]], "id": "P6-vl7-17", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Autohändler A verkauft dem K einen Neuwagen und erklärt im Kaufvertrag: „Wir garantieren einen Verbrauch von höchstens 5,0 l auf 100 km nach WLTP.“ Ein Gutachten ergibt, dass der Wagen schon bei Übergabe 6,2 l verbraucht. A hält dagegen, er habe nur eine Haltbarkeitsgarantie gegeben, deren Fall nicht eingetreten sei, weil der Wagen bis heute nicht defekt sei.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K hat keine Rechte, weil eine Garantie nur bei einem späteren Defekt während der Garantiezeit eingreift.", "Falsch. Das gilt für die Haltbarkeitsgarantie. Hier hat A eine bestimmte Beschaffenheit (Verbrauch) bei Übergabe zugesagt."], ["K hat nur Rechte aus der Garantie, weil eine Garantie die gesetzlichen Mängelrechte verdrängt (§ 443).", "Falsch. Die Garantie besteht neben den gesetzlichen Rechten (§ 443 I: „unbeschadet der gesetzlichen Ansprüche“)."], ["K hat keine Rechte, weil Verbrauchsangaben nach WLTP nur unverbindliche Herstellerwerte sind.", "Falsch. A hat den Wert im Vertrag ausdrücklich garantiert. Damit ist er vereinbarte und garantierte Beschaffenheit."], ["Beschaffenheitsgarantie: K hat Mängelrechte, A haftet auch ohne Verschulden (§§ 443, 276 I 1).", "Richtig. A hat für eine bestimmte Soll-Beschaffenheit bei Gefahrübergang eingestanden. Der Mehrverbrauch ist ein Mangel; wegen der Garantie kommt es auf Verschulden nicht an."], ["K kann nur von einem Hersteller Ansprüche geltend machen, weil Verbrauchsangaben vom Hersteller stammen.", "Falsch. Garantiegeber ist A selbst, der die Zusage im Kaufvertrag gemacht hat."], ["K kann zurücktreten, aber erst, nachdem er A zwei Nachbesserungsversuche ermöglicht hat (§ 440 S. 2).", "Falsch. Laut Sachverhalt geht es um die Einordnung der Garantie. Zudem lässt sich ein konstruktionsbedingter Mehrverbrauch oft gar nicht nachbessern."]], "id": "P6-vl7-18", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Händler H verkauft der Verbraucherin V einen Staubsauger mit einer „3-Jahres-Händlergarantie“. Die Garantieerklärung ist in kaum verständlichem Fachjargon abgefasst, nennt weder Namen noch Anschrift des Garantiegebers und enthält keinen Hinweis darauf, dass V's gesetzliche Rechte unberührt bleiben. Nach 30 Monaten fällt der Motor aus. H meint, die Garantie sei wegen der Formfehler unwirksam.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Die Garantie ist unwirksam, weil sie die Pflichtangaben des § 479 nicht enthält.", "Falsch. § 479 III bestimmt ausdrücklich, dass die Wirksamkeit der Garantie nicht dadurch berührt wird, dass Anforderungen nicht erfüllt sind."], ["Die Garantie ist unwirksam, weil sie unverständlich formuliert ist und V mit ihrem Inhalt deshalb nicht rechnen musste (§ 305c I).", "Falsch. Die einfache und verständliche Abfassung (§ 479 I) ist eine Pflicht des Garantiegebers. Ein Verstoß macht die Garantie nicht unwirksam (§ 479 III)."], ["Die Garantie ist trotz der Mängel der Erklärung wirksam; V kann den Motorschaden aus der Garantie geltend machen (§§ 443, 479 III).", "Richtig. Die Pflichtangaben sollen den Verbraucher schützen. Deshalb bleibt die Garantie wirksam, auch wenn H sie nicht erfüllt."], ["Die Garantie ist wirksam, gilt aber nur zwei Jahre, weil Garantien beim Verbrauchsgüterkauf nicht länger als die Gewährleistung laufen dürfen.", "Falsch. Eine solche Höchstdauer gibt es nicht. Inhalt und Dauer der Garantie bestimmt der Garantiegeber."], ["V hat nur Gewährleistungsrechte, die nach 30 Monaten verjährt sind, weil die fehlerhafte Garantie in eine Gewährleistung umgedeutet wird (§ 140).", "Falsch. Eine Umdeutung findet nicht statt. Die Garantie bleibt als eigene Anspruchsgrundlage bestehen."], ["Die Garantie ist schwebend unwirksam, bis H eine ordnungsgemäße, verständliche Fassung nachreicht.", "Falsch. Einen Schwebezustand sieht § 479 nicht vor. Die Garantie ist von Anfang an wirksam."]], "id": "P6-vl7-19", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Händler H verkauft der Verbraucherin V (1) ein neues Smartphone und (2) einen gebrauchten Laptop, den H von seinem Lieferanten L als Gebrauchtware bezogen hat. Beide Geräte haben einen Mangel, der schon bei L vorlag. H repariert auf eigene Kosten (Smartphone 120 €, Laptop 90 €) und verlangt beide Beträge von L zurück. L meint, ihn treffe kein Verschulden; außerdem habe H die Kosten freiwillig übernommen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["H kann beide Beträge von L verlangen, weil der Rückgriff verschuldensunabhängig für alle verkauften Sachen gilt (§ 445a I).", "Falsch. Die Regelungen zum Rückgriff sind nach dem Skript auf neu hergestellte Sachen beschränkt."], ["H kann keinen der Beträge verlangen, weil L nichts verschuldet hat und Schadensersatz Vertretenmüssen voraussetzt (§ 280 I).", "Falsch. § 445a I gibt einen Aufwendungsersatzanspruch, der kein Verschulden voraussetzt."], ["H kann keinen der Beträge verlangen, weil er gegenüber V zur Reparatur gar nicht verpflichtet war (§ 445a I).", "Falsch. H musste als Verkäufer gegenüber V nacherfüllen (§ 439 II). Diese Aufwendungen sind gerade Gegenstand des Rückgriffs."], ["H kann nur die 90 € für den Laptop verlangen, weil bei gebrauchten Sachen der Lieferant stärker haftet.", "Falsch. Genau umgekehrt: Für gebrauchte Sachen gibt es den besonderen Rückgriff nicht."], ["H kann die 120 € für das neue Smartphone nach § 445a I ohne Verschulden des L verlangen, die 90 € für den gebrauchten Laptop nicht.", "Richtig. Der verschuldensunabhängige Erstattungsanspruch gilt nur beim Verkauf neu hergestellter Sachen. Für den Laptop bleiben H nur die normalen Mängelrechte gegen L."], ["H kann beide Beträge verlangen, aber nur, wenn V Unternehmerin ist (§ 445a I).", "Falsch. § 445a gilt beim Verkauf neu hergestellter Sachen; dass V Verbraucherin ist, schließt den Rückgriff gerade nicht aus."]], "id": "P6-vl7-20", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Die Spedition S GmbH kauft beim Nutzfahrzeughändler N einen gebrauchten Lkw für 48.000 €. N weiß, dass der Kilometerzähler manipuliert wurde und der Lkw 150.000 km mehr gelaufen ist, sagt aber nichts. S entdeckt die Manipulation und erklärt sofort den Rücktritt, ohne N eine Frist zur Nacherfüllung zu setzen. N bietet an, „den Schaden irgendwie auszugleichen“.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Der Rücktritt ist unwirksam, weil S als Unternehmerin dem Verkäufer zuerst eine angemessene Frist setzen muss (§ 323 I).", "Falsch. Die Frist ist hier entbehrlich: Bei arglistiger Täuschung ist dem Käufer eine Nacherfüllung durch den Verkäufer nach dem BGH in der Regel unzumutbar."], ["Der Rücktritt ist wirksam, weil die Nacherfüllung nach der arglistigen Täuschung für S unzumutbar ist (§ 440 S. 1 Var. 3).", "Richtig. Wer arglistig täuscht, hat das Vertrauen zerstört, das für eine Nacherfüllung nötig ist. Außerdem ist die höhere Laufleistung nicht behebbar (§ 326 V)."], ["Der Rücktritt ist wirksam, aber nur, weil S stattdessen hätte anfechten müssen und der Rücktritt als Anfechtung umgedeutet wird (§ 140).", "Falsch. Rücktritt und Anfechtung nach § 123 stehen nebeneinander. Eine Umdeutung ist nicht nötig, weil der Rücktritt selbst wirksam ist."], ["Der Rücktritt ist unwirksam, weil § 440 im Handelsverkehr nicht gilt und die Kaufleute § 377 HGB vorrangig anwenden müssen.", "Falsch. § 440 gilt für alle Kaufverträge außer dem Verbrauchsgüterkauf. § 377 HGB betrifft die Rüge, nicht die Entbehrlichkeit der Frist."], ["Der Rücktritt ist unwirksam, weil ein Kilometerstand beim Gebrauchtwagen nie vereinbarte Beschaffenheit ist (§ 434 II).", "Falsch. Die Laufleistung gehört zur üblichen Beschaffenheit, die ein Käufer erwarten kann (§ 434 III). Ein manipulierter Zähler weicht davon erheblich ab."], ["Der Rücktritt ist wirksam, weil beim Verkauf durch einen Händler immer die Sonderregeln des Verbrauchsgüterkaufs gelten (§ 475d).", "Falsch. § 475d setzt einen Verbraucher als Käufer voraus. S ist eine GmbH."]], "id": "P6-vl7-21", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Elektromarkt E eine originalverpackte Spülmaschine. Wegen eines Produktionsfehlers des Herstellers platzt nach zwei Wochen ein Schlauch; das Wasser beschädigt V's Parkett (Schaden 2.500 €). Der Fehler war von außen nicht erkennbar; E hat die Maschine nicht geöffnet. V meldet den Mangel sofort, doch E unternimmt trotz Ablaufs einer angemessenen Frist nichts. V verlangt von E die 2.500 € und tritt außerdem zurück.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["V kann zurücktreten, die 2.500 € aber nicht von E verlangen, weil E den Fehler nicht zu vertreten hat (§§ 280 I 2, 323).", "Richtig. Rücktritt ist verschuldensunabhängig. Für den Mangelfolgeschaden braucht es Vertretenmüssen – ein Händler muss originalverpackte Ware nicht untersuchen, und der Hersteller ist nicht sein Erfüllungsgehilfe."], ["V kann von E die 2.500 € verlangen, weil E sich das Verschulden des Herstellers als Erfüllungsgehilfe zurechnen lassen muss (§ 278).", "Falsch. Der Hersteller hilft nicht bei der Erfüllung der Verkäuferpflichten, sondern stellt die Ware her. Er ist nach h. M. nicht Erfüllungsgehilfe des Händlers."], ["V kann von E die 2.500 € verlangen, weil Mängelrechte beim Verbrauchsgüterkauf generell verschuldensunabhängig sind (§ 475).", "Falsch. Auch beim Verbrauchsgüterkauf setzen Schadensersatzansprüche Vertretenmüssen voraus. Verschuldensunabhängig sind nur Nacherfüllung, Rücktritt und Minderung."], ["V kann weder zurücktreten noch Schadensersatz verlangen, weil der Mangel vom Hersteller stammt und E dafür nicht einstehen muss.", "Falsch. Für die Mängelrechte kommt es nicht darauf an, wer den Mangel verursacht hat. Rücktritt ist gegen E möglich."], ["V kann von E die 2.500 € nur verlangen, wenn sie ihm vorher eine Frist zur Reparatur des Parketts gesetzt hat (§ 281 I).", "Falsch. Für den Mangelfolgeschaden gilt § 280 I ohne Fristsetzung. Der Anspruch scheitert am Vertretenmüssen, nicht an einer Frist."], ["V muss sich wegen des Parketts an ihre Hausratversicherung halten; Ersatzansprüche gegen Dritte bestehen nicht.", "Falsch. Gegen den Hersteller kommen Ansprüche nach dem Produkthaftungsgesetz und aus § 823 I in Betracht."]], "id": "P6-vl7-22", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "K hat beim Händler V ein Sofa gekauft. Wegen eines erheblichen Polsterschadens, den V trotz Frist nicht beseitigt, schickt K am Montag eine E-Mail: „Hiermit trete ich vom Kaufvertrag zurück.“ Am Mittwoch hat K das Sofa doch liebgewonnen und schreibt: „Ich nehme den Rücktritt zurück und mindere stattdessen um 300 €.“ V besteht auf der Rückabwicklung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K kann den Rücktritt bis zur Rückgabe des Sofas jederzeit widerrufen, weil das Schuldverhältnis erst dann umgestaltet ist (§ 346 I).", "Falsch. Die Umgestaltung tritt schon mit Zugang der Rücktrittserklärung ein, nicht erst mit der Rückgabe."], ["K kann mindern, weil Rücktritt und Minderung beliebig ausgetauscht werden können, solange V noch nichts zurückgezahlt hat.", "Falsch. Mit dem Rücktritt hat K sein Wahlrecht ausgeübt. Ein späterer Wechsel zur Minderung ist ausgeschlossen."], ["K kann mindern, weil ein Rücktritt per E-Mail mangels Schriftform unwirksam ist (§§ 126, 349).", "Falsch. Der Rücktritt ist formfrei; eine E-Mail genügt (§ 349)."], ["Der Rücktritt ist unwirksam, weil K ihn nicht begründet hat; eine Begründung ist Wirksamkeitsvoraussetzung (§ 349).", "Falsch. § 349 verlangt nur eine Erklärung gegenüber dem anderen Teil. Eine Begründung ist nicht erforderlich."], ["Der Rücktritt wirkte mit Zugang und ist unwiderruflich; V kann Rückabwicklung verlangen (§§ 349, 346).", "Richtig. Der Rücktritt ist ein Gestaltungsrecht. Mit Zugang wird der Vertrag unwiderruflich zum Rückabwicklungsverhältnis. Nur ein Einvernehmen mit V könnte daran etwas ändern."], ["Der Rücktritt ist erst wirksam, wenn V ihn annimmt; da V noch nicht reagiert hat, kann K noch mindern.", "Falsch. Der Rücktritt ist eine einseitige, empfangsbedürftige Willenserklärung. Eine Annahme durch V ist nicht nötig."]], "id": "P6-vl7-23", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Die Druckerei D GmbH kauft beim Händler H eine Falzmaschine für 20.000 €. Die Maschine verursacht ständig Papierstaus, der Mangel ist erheblich. H hat den Defekt nach eigener Aussage „schon geahnt“ und trotz Frist nicht beseitigt. D kauft bei einem anderen Händler ein vergleichbares Gerät für 23.000 € und verlangt von H Rückzahlung der 20.000 € und die Mehrkosten. H will die Maschine aber nicht zurücknehmen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["D kann nur den kleinen Schadensersatz verlangen, weil sie die Maschine schon in Betrieb genommen hat (§ 281 I 3).", "Falsch. Die Inbetriebnahme schließt den großen Schadensersatz nicht aus. Es kommt nur auf die Erheblichkeit des Mangels an."], ["D kann die 3.000 € Mehrkosten verlangen, muss aber die Maschine behalten, weil H sie nicht zurücknehmen will.", "Falsch. Beim großen Schadensersatz kann der Verkäufer die Sache zurückfordern; er kann die Rücknahme nicht verweigern, um den Käufer an der Sache festzuhalten."], ["D kann die 20.000 € nur über einen Rücktritt zurückverlangen; Schadensersatz und Rücktritt schließen sich aus.", "Falsch. § 325 erlaubt Schadensersatz neben dem Rücktritt. Der große Schadensersatz umfasst ohnehin die Rückabwicklung."], ["D kann Schadensersatz statt der ganzen Leistung verlangen: Rückgabe der Maschine gegen 20.000 € plus 3.000 € Mehrkosten (§§ 280 I, III, 281 I 3, V).", "Richtig. Bei erheblichem Mangel kann der Käufer die Sache zurückgeben und den gesamten Schaden verlangen, hier Kaufpreis und Mehrkosten des Deckungskaufs (zusammen 23.000 €)."], ["D kann 23.000 € verlangen, aber nur, wenn H den Mangel vorsätzlich verursacht hat (§ 276 I).", "Falsch. Für Schadensersatz genügt Fahrlässigkeit. H hat den Defekt geahnt und trotz Frist nicht beseitigt; das Vertretenmüssen wird zudem vermutet (§ 280 I 2)."], ["D kann nur die Mehrkosten von 3.000 € verlangen, weil der Kaufpreis beim Schadensersatz nicht ersetzt wird.", "Falsch. Beim großen Schadensersatz wird D so gestellt, als wäre ordnungsgemäß erfüllt worden. Dazu gehört die Rückgewähr des Kaufpreises gegen Rückgabe der Sache."]], "id": "P6-vl7-24", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Unternehmer U kauft beim Händler H eine Kaffeemaschine für sein Büro; Ablieferung am 2. Mai 2023. Ab Herbst 2024 zeigt sich ein Mangel an der Brühgruppe, U unternimmt aber nichts. Am 15. Juli 2025 erklärt U den Rücktritt und verlangt den Kaufpreis zurück. H erhebt die Einrede der Verjährung. U meint, der Rücktritt sei ein Gestaltungsrecht und verjähre nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Der Rücktritt ist wirksam, weil nur Ansprüche verjähren und der Rücktritt als Gestaltungsrecht keiner Verjährung unterliegt (§ 194 I).", "Falsch. Der Rücktritt verjährt zwar nicht, er ist aber nach § 218 I unwirksam, wenn der Nacherfüllungsanspruch verjährt ist und der Schuldner sich darauf beruft."], ["Der Rücktritt ist wirksam, weil sich der Mangel innerhalb der Verjährungsfrist gezeigt hat und die Verjährung deshalb vier Monate gehemmt ist (§ 475e III).", "Falsch. § 475e III gilt nur beim Verbrauchsgüterkauf. U ist Unternehmer. Außerdem hätten vier Monate ab Herbst 2024 nicht bis Juli 2025 gereicht."], ["Der Rücktritt ist unwirksam, weil der Nacherfüllungsanspruch seit Mai 2025 verjährt ist und H sich darauf beruft (§§ 438 IV 1, 218 I).", "Richtig. Die zwei Jahre ab Ablieferung liefen am 2. Mai 2025 ab. Ein Rücktritt danach ist unwirksam, wenn der Verkäufer die Verjährung geltend macht."], ["Der Rücktritt ist wirksam, weil für Rücktrittsrechte die dreijährige Regelverjährung ab Jahresende gilt (§§ 195, 199).", "Falsch. Für den Rücktritt wegen eines Mangels gilt nicht die Regelverjährung, sondern § 438 IV i. V. m. § 218."], ["Der Rücktritt ist unwirksam, weil U den Mangel nicht unverzüglich gerügt hat und deshalb jede Gewährleistung verloren ist (§ 377 HGB).", "Falsch. Ob § 377 HGB greift, hängt davon ab, ob H Kaufmann ist – das ist offen. Sicher ist der Rücktritt jedenfalls nach § 218 unwirksam."], ["Der Rücktritt ist wirksam, aber U muss H einen Nutzungsersatz von zwei Jahren zahlen (§ 346 I).", "Falsch. Auf Nutzungsersatz kommt es nicht an, weil der Rücktritt schon unwirksam ist."]], "id": "P6-vl7-25", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Verbraucher V kauft im Onlineshop des Softwarehauses S eine Lizenz für ein Bildbearbeitungsprogramm zum Download für 89 €. Er zahlt sofort. S schickt den versprochenen Download-Link nicht. Nach einer Woche erklärt V ohne weitere Nachricht an S: „Ich beende den Vertrag und will mein Geld zurück.“ S meint, V hätte ihn erst zur Bereitstellung auffordern müssen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["V konnte sofort vom Vertrag zurücktreten, weil für Software das Kaufrecht und damit § 323 gilt.", "Falsch. Für digitale Produkte gelten die §§ 327 ff. als besonderes Gewährleistungsrecht. Sie gehen dem Kaufrecht vor."], ["V konnte den Vertrag beenden, weil der Unternehmer beweisen muss, dass er bereitgestellt hat, und S das nicht kann (§ 327b VI).", "Falsch. Die Beweislastregel betrifft nur die Frage, ob bereitgestellt wurde. Sie macht die vorherige Aufforderung nicht entbehrlich."], ["V kann den Vertrag nicht beenden, sondern nur Schadensersatz verlangen, weil eine Beendigung bei digitalen Produkten ausgeschlossen ist.", "Falsch. § 327c I gibt dem Verbraucher gerade ein Recht zur Vertragsbeendigung, wenn die Bereitstellung trotz Aufforderung ausbleibt."], ["V konnte den Vertrag beenden, weil die Bereitstellung bei Online-Käufen spätestens nach einer Woche geschuldet ist und danach automatisch Verzug eintritt (§ 286).", "Falsch. Die Beendigung richtet sich nicht nach Verzugsregeln, sondern nach § 327c. Dort ist eine Aufforderung grundsätzlich Voraussetzung."], ["V konnte den Vertrag sofort beenden, weil Verbraucher bei Fernabsatzverträgen ohnehin widerrufen können (§ 312g).", "Falsch. Eine Beendigungserklärung wegen Nichtbereitstellung ist kein Widerruf. Außerdem fragt der Fall nach den Rechten aus § 327c."], ["Die Beendigung ist unwirksam, weil V die Bereitstellung nicht zuvor verlangt hat (§ 327c I).", "Richtig. Das Skript nennt die Aufforderung als Grundvoraussetzung. Sie ist nur in den Fällen des § 327c III entbehrlich, z. B. wenn S die Bereitstellung verweigert – dafür gibt der Sachverhalt nichts her."]], "id": "P6-vl7-26", "tag": "VL 7 · Skript", "neu": true}, {"topic": "kauf", "sv": "Studentin S abonniert für 12 € im Monat eine Sprachlern-App des Anbieters A. Seit einem Update stürzt die App bei jeder Übung ab. S verlangt die Behebung; A tut nichts. Nach drei Monaten möchte S „vom Kaufvertrag zurücktreten“ und für die fehlerhafte Zeit einen Teil der Gebühren zurück. A meint, bei Apps gebe es keine Gewährleistung, und außerdem müsse S erst beweisen, dass der Fehler von A stammt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["S kann nach §§ 437 Nr. 2, 323 vom Kaufvertrag zurücktreten, weil die App eine Kaufsache ist.", "Falsch. Eine App ist ein digitales Produkt. Es gelten die §§ 327 ff. mit eigenen Rechten; statt „Rücktritt“ gibt es die Vertragsbeendigung."], ["S kann den Vertrag beenden oder mindern; der Mangel wird zu ihren Gunsten vermutet (§§ 327m, 327n, 327k).", "Richtig. Bei einem Produktmangel hat S Nacherfüllung (§ 327l), Vertragsbeendigung (§ 327m), Minderung (§ 327n) und ggf. Schadensersatz. Die Beweislastumkehr des § 327k hilft ihr."], ["S hat keine Rechte, weil digitale Produkte nur einer Garantie des Herstellers unterliegen, nicht einer Gewährleistung.", "Falsch. Die §§ 327d ff. enthalten ein eigenes, umfangreiches Gewährleistungsrecht für digitale Produkte."], ["S kann nur Nacherfüllung verlangen, weil die Vertragsbeendigung bei digitalen Abonnements ausgeschlossen ist.", "Falsch. Die Vertragsbeendigung ist ausdrücklich vorgesehen (§ 327m), wenn die Nacherfüllung scheitert oder verweigert wird."], ["S muss beweisen, dass der Absturz schon bei Bereitstellung angelegt war, weil sie die App drei Monate genutzt hat (§ 477).", "Falsch. § 477 betrifft den Warenkauf. Für digitale Produkte gilt § 327k, und bei dauerhafter Bereitstellung trägt grundsätzlich der Unternehmer die Beweislast für den gesamten Zeitraum."], ["S hat Rechte, muss aber erst zwei Nacherfüllungsversuche abwarten, weil § 440 S. 2 auch für digitale Produkte gilt.", "Falsch. § 440 gehört zum Kaufrecht. Die Rechte bei digitalen Produkten regeln §§ 327i ff. eigenständig; S hat Behebung verlangt, und A hat nichts getan."]], "id": "P6-vl7-27", "tag": "VL 7 · Skript", "neu": true}];
L.forEach(q=>{ if(!W.some(x=>x.id===q.id)) W.push(q); });
window.WPR_LOES = Object.assign(window.WPR_LOES || {}, {"P6-vl7-0": {"k": "Der Rücktritt ist ", "w": ["Frage: Musste S nach dem ersten erfolglosen Reparaturversuch noch eine Frist setzen?", "Rücktritt wegen Mangels: §§ 437 Nr. 2, 323 I – grundsätzlich erfolglose Frist zur Nacherfüllung. Ausnahmen regeln §§ 323 II, 440 – beim Verbrauchsgüterkauf aber nicht: Dort gilt abschließend § 475d (Skript VL 7).", "§ 475d I Nr. 2: Die Frist ist entbehrlich, wenn sich trotz der vom Unternehmer versuchten Nacherfüllung ein Mangel zeigt. Beim Verbrauchsgüterkauf reicht also schon ein Fehlschlag (anders § 440 S. 2: in der Regel zwei Versuche).", "S kauft privat beim Händler (§§ 13, 14, 474) → § 475d gilt. Der Mangel ist erheblich (Gerät unbrauchbar, § 323 V 2).", "Ergebnis: d – der Rücktritt ist wirksam."]}, "P6-vl7-1": {"k": "Der Rücktritt ist ", "w": ["Frage: Durfte B nach dem ersten misslungenen Nachbesserungsversuch sofort zurücktreten?", "Rücktritt: §§ 437 Nr. 2, 323 I. B hat eine Frist gesetzt, F hat aber innerhalb dieser Frist nachgebessert – es kommt also darauf an, ob die Nacherfüllung fehlgeschlagen ist (§ 440 S. 1 Var. 2).", "§ 440 S. 2: Eine Nachbesserung gilt nach dem erfolglosen zweiten Versuch als fehlgeschlagen, wenn sich nicht aus Art der Sache, des Mangels oder sonstigen Umständen etwas anderes ergibt.", "B ist Unternehmerin → kein Verbrauchsgüterkauf → § 475d gilt nicht. Nach einem Versuch ist die Nacherfüllung noch nicht fehlgeschlagen.", "Ergebnis: a – der Rücktritt ist (noch) unwirksam."]}, "P6-vl7-2": {"k": "Der Rücktritt ist ", "w": ["Frage: Reicht H's Abwimmeln, damit V ohne Frist zurücktreten kann?", "Rücktritt: §§ 437 Nr. 2, 323 I; Mangel liegt vor. Grundsatz: Fristsetzung zur Nacherfüllung.", "Beim Verbrauchsgüterkauf (V Verbraucher, H Unternehmer) regelt § 475d I die Entbehrlichkeit abschließend; § 323 II und § 440 sind nicht anwendbar.", "§ 475d I Nr. 4: Die Frist ist entbehrlich, wenn der Unternehmer die Nacherfüllung verweigert. Nach dem Skript genügt hier die einfache Verweigerung – sie muss nicht ernsthaft und endgültig sein (anders § 323 II Nr. 1 außerhalb des Verbrauchsgüterkaufs). Der Verweis auf den Hersteller ist eine Verweigerung.", "Ergebnis: e – der Rücktritt ist wirksam."]}, "P6-vl7-3": {"k": "3.000 €: Der Preis", "w": ["Frage: Um wie viel wird der Kaufpreis gemindert?", "Minderung (§§ 437 Nr. 2, 441): Voraussetzungen wie beim Rücktritt (Mangel, erfolglose Frist) – erfüllt; Erheblichkeit ist nicht nötig (§ 441 I 2).", "Berechnung (§ 441 III): geminderter Preis = Kaufpreis × (Wert mangelhaft ÷ Wert mangelfrei) = 9.000 × 8.000/12.000 = 6.000 €. Achtung: Die Formel im Skript liefert den neuen Kaufpreis, nicht den Erstattungsbetrag.", "K hat 9.000 € gezahlt → zu viel gezahlt: 3.000 €, Erstattung nach § 441 IV i. V. m. §§ 346 I, 347 I.", "Ergebnis: c – 3.000 €."]}, "P6-vl7-4": {"k": "Der Rücktritt ist ", "w": ["Frage: Kann U nach erklärter Minderung wegen desselben Mangels noch zurücktreten?", "Minderung (§§ 437 Nr. 2, 441 I) ist ein Gestaltungsrecht, erklärt durch einseitige, empfangsbedürftige Willenserklärung. Mit Zugang ist der Kaufpreis herabgesetzt.", "Das Skript betont: Die Minderung ist unwiderruflich – der Käufer kann nicht nachträglich zurücktreten. Sie wird „statt zurückzutreten“ erklärt.", "Es geht um denselben Mangel (Klimaanlage). Nach dem BGH ist dann auch ein Wechsel zum großen Schadensersatz ausgeschlossen; kleiner Schadensersatz für weitere Schäden bleibt denkbar.", "Ergebnis: f – der Rücktritt ist unwirksam."]}, "P6-vl7-5": {"k": "G kann nur kleinen", "w": ["Frage: Kann G großen Schadensersatz (Rückgabe + Mehrkosten) oder nur kleinen Schadensersatz verlangen?", "Schadensersatz statt der Leistung (§§ 437 Nr. 3, 280 I, III, 281): Mangel (+), Frist entbehrlich wegen Verweigerung (§ 281 II), Vertretenmüssen (+): H hätte den Fehler bei seiner Endkontrolle bemerken müssen (vermutet, § 280 I 2).", "Großer Schadensersatz (statt der ganzen Leistung): Sache zurück (§ 281 V), voller Schaden. Nur bei erheblichem Mangel (§ 281 I 3). 60 € bei 1.200 € (5 %) und ein schmaler Farbstreifen → unerheblich.", "Kleiner Schadensersatz: Käufer behält die Sache und bekommt den Minderwert – auch bei unerheblichem Mangel.", "Ergebnis: b – G behält den Monitor und bekommt 60 €."]}, "P6-vl7-6": {"k": "K bleibt zur Zahlu", "w": ["Frage: Wird K von der Zahlungspflicht frei, weil die Nacherfüllung unmöglich ist?", "Allgemeine Regel: Wird der Schuldner nach § 275 frei, entfällt die Gegenleistung automatisch (§ 326 I 1).", "Ausnahme § 326 I 2: Das gilt nicht, wenn der Schuldner bei nicht vertragsgemäßer Leistung die Nacherfüllung nach § 275 nicht zu erbringen braucht. Begründung im Skript: Der Käufer hat ja eine (mangelhafte) Sache bekommen und muss sich zwischen seinen Rechten entscheiden.", "K kann nach § 326 V ohne Frist zurücktreten oder nach § 441 mindern, ggf. Schadensersatz nach § 311a II verlangen. Bis er sich entscheidet, bleibt der Restkaufpreis von 13.000 € geschuldet.", "Ergebnis: d ist richtig."]}, "P6-vl7-7": {"k": "U kann ohne Frist ", "w": ["Zwei Fragen: (1) Rücktritt ohne Frist? (2) Schadensersatz?", "Mangel: „unfallfrei“ ist vereinbarte Beschaffenheit (§ 434 II 1 Nr. 1); ein Unfallwagen weicht davon ab. Der Mangel ist nicht behebbar – die Vergangenheit lässt sich nicht ändern, Nacherfüllung unmöglich (§ 275 I), und zwar schon bei Vertragsschluss (anfänglich).", "Zu (1): §§ 437 Nr. 2, 326 V – Rücktritt ohne Fristsetzung; verschuldensunabhängig; der Mangel ist erheblich.", "Zu (2): Anfänglich unbehebbarer Mangel → Schadensersatz statt der Leistung aus §§ 437 Nr. 3, 311a II. Er entfällt, wenn der Verkäufer das Leistungshindernis bei Vertragsschluss nicht kannte und seine Unkenntnis nicht zu vertreten hat (§ 311a II 2). A hatte keinen Anlass zu Zweifeln. Der Vorbesitzer ist nicht sein Erfüllungsgehilfe.", "Ergebnis: c ist richtig."]}, "P6-vl7-8": {"k": "V kann zurücktrete", "w": ["Frage: Kann V neben dem Rücktritt die Kosten der nutzlos gewordenen Bühne ersetzt verlangen?", "Rücktritt (§§ 437 Nr. 2, 323): Mangel, erfolglose Frist, erheblich → wirksam. Nach § 325 schließt der Rücktritt Schadensersatz nicht aus.", "Aufwendungsersatz (§§ 437 Nr. 3, 284): „Anstelle des Schadensersatzes statt der Leistung“ kann der Gläubiger Ersatz der Aufwendungen verlangen, die er im Vertrauen auf den Erhalt der Leistung gemacht hat und billigerweise machen durfte.", "Voraussetzungen des Schadensersatzes statt der Leistung (§§ 280 I, III, 281): Frist (+), Vertretenmüssen (+) – H kannte den Mangel. Die Bühne wurde nur für diese Anlage gebaut und ist nutzlos; der Zweck (Vereinsfeier) ist ideell, deshalb passt § 284 besser als ein Gewinnersatz.", "Ergebnis: f ist richtig."]}, "P6-vl7-9": {"k": "V hat Mängelrechte", "w": ["Frage: Verliert V ihre Mängelrechte, weil sie den Kratzer beim Kauf gesehen hat?", "Grundsatz § 442 I 1: Kennt der Käufer den Mangel bei Vertragsschluss, sind seine Rechte ausgeschlossen.", "Beim Verbrauchsgüterkauf (V Verbraucherin, M Unternehmer) gilt § 442 nicht (§ 475 III 2, Skript VL 7). Eine geringere Beschaffenheit kann nur nach § 476 I 2 vereinbart werden: eigener Hinweis vor Vertragsschluss und ausdrückliche, gesonderte Vereinbarung.", "Hier wurde über den Kratzer weder gesprochen noch etwas vereinbart → der Tisch muss den objektiven Anforderungen (§ 434 III) entsprechen; er tut es nicht → Mangel, Nacherfüllung (§§ 437 Nr. 1, 439).", "Ergebnis: a ist richtig."]}, "P6-vl7-10": {"k": "K kann zurücktrete", "w": ["Frage: Welche Teile des Gewährleistungsausschlusses sind beim Verbrauchsgüterkauf wirksam?", "Verbrauchsgüterkauf (§ 474 I). § 476 I 1: Vor Mitteilung eines Mangels kann sich der Unternehmer nicht auf Vereinbarungen berufen, die zum Nachteil des Verbrauchers von §§ 433–435, 437, 439–443 abweichen → Ausschluss von Rücktritt und Minderung unwirksam, auch individuell.", "§ 476 III: Das gilt nicht für den Ausschluss oder die Beschränkung des Schadensersatzes – dafür gelten nur §§ 307–309 (bei AGB) und § 444 (Arglist, Garantie). Hier: individuell vereinbart, keine Arglist, keine Garantie → wirksam.", "Rücktritt: Nachbesserung fehlgeschlagen → Frist entbehrlich (§ 475d I Nr. 2), Mangel erheblich → wirksam.", "Ergebnis: e – Rücktritt ja, 40 € nein."]}, "P6-vl7-11": {"k": "M kann Nachlieferu", "w": ["Frage: Verliert M ihre Mängelrechte, weil sie erst nach vier Monaten rügt?", "§ 377 HGB: Beim beiderseitigen Handelskauf (beide Kaufleute, §§ 1–6 HGB, Geschäft gehört zum Handelsgewerbe, §§ 343, 344 HGB) muss der Käufer die Ware unverzüglich untersuchen und Mängel rügen; sonst gilt die Ware als genehmigt (§ 377 II HGB).", "Hier wäre der Mangel bei einer Stichprobe aufgefallen – ohne Vereinbarung hätte M ihre Rechte verloren.", "Aber: § 377 HGB ist dispositiv (Skript VL 7) und kann durch Vereinbarung abbedungen werden; das Skript nennt ausdrücklich auch AGB. Hier geschah es im Rahmenvertrag. Es bleibt bei §§ 437 ff. und der Verjährung des § 438.", "Ergebnis: b – M kann Nachlieferung verlangen."]}, "P6-vl7-12": {"k": "G behält seine Män", "w": ["Frage: Musste G als Kaufmann die Truhe sofort untersuchen und rügen?", "§ 377 I HGB setzt voraus, dass der Kauf „für beide Teile ein Handelsgeschäft“ ist: Beide Parteien müssen Kaufleute sein (§§ 1–6 HGB) und das Geschäft muss zu ihrem jeweiligen Handelsgewerbe gehören (§§ 343, 344 HGB).", "G ist Kaufmann, der Kauf gehört zu seinem Restaurant. P ist Privatmann und verkauft aus einer Haushaltsauflösung → für P kein Handelsgeschäft.", "Ohne beiderseitigen Handelskauf keine Rügeobliegenheit und keine Genehmigungsfiktion. Es gelten nur §§ 437 ff. mit der Verjährung des § 438.", "Ergebnis: d – G behält seine Mängelrechte."]}, "P6-vl7-13": {"k": "Nicht verjährt: Di", "w": ["Frage: Ist die Verkürzung der Verjährung auf ein Jahr wirksam?", "Regel: Mängelansprüche verjähren in zwei Jahren ab Ablieferung (§ 438 I Nr. 3, II), auch bei gebrauchten Sachen.", "Verbrauchsgüterkauf: Verkürzung nur bei gebrauchten Sachen, und zwar auf mindestens ein Jahr ab Ablieferung, und nur wenn (Nr. 1) der Verbraucher vor Abgabe seiner Vertragserklärung von der Verkürzung eigens in Kenntnis gesetzt wurde und (Nr. 2) die Verkürzung im Vertrag ausdrücklich und gesondert vereinbart wurde (§ 476 II).", "Hier: nur eine Klausel unter Ziffer 12 der AGB, kein Hinweis, keine gesonderte Vereinbarung → unwirksam. Es bleibt bei zwei Jahren.", "Ergebnis: f – nach 16 Monaten nicht verjährt."]}, "P6-vl7-14": {"k": "K kann 1.500 € ver", "w": ["Frage: Haftet P trotz Gewährleistungsausschluss und obwohl er den Motortausch nicht kannte?", "Unter Privatleuten kann die Gewährleistung grundsätzlich ganz ausgeschlossen werden; Grenze ist nur § 444 (Skript VL 7).", "§ 444: Auf den Ausschluss kann sich der Verkäufer nicht berufen, soweit er den Mangel arglistig verschwiegen oder eine Garantie für die Beschaffenheit übernommen hat. P hat garantiert, dass der Motor nicht getauscht ist.", "Haftung: Der Mangel (Fremdmotor) ist nicht behebbar → §§ 437 Nr. 3, 311a II. Verschulden ist nicht nötig, weil P eine Garantie übernommen hat (§ 276 I 1); auch § 311a II 2 entlastet ihn deshalb nicht.", "Ergebnis: c – 1.500 €."]}, "P6-vl7-15": {"k": "Nicht verjährt: We", "w": ["Frage: Ist der Anspruch wegen des wieder aufgetretenen Defekts am 20. April 2026 verjährt?", "Grundregel: 2 Jahre ab Ablieferung (§ 438 I Nr. 3, II) → regulär Ende am 10. März 2026.", "Verbrauchsgüterkauf – Ablaufhemmungen (§ 475e): III: Zeigt sich der Mangel innerhalb der Frist, tritt die Verjährung nicht vor Ablauf von vier Monaten nach dem ersten Auftreten ein → nicht vor dem 1. März 2026 (bringt hier nichts). IV: Ist der Mangel geltend gemacht und nachgebessert worden, tritt die Verjährung nicht vor Ablauf von zwei Monaten nach Übergabe der nachgebesserten Ware ein → nicht vor dem 25. April 2026.", "Maßgeblich ist das späteste Ende: 25. April 2026. Am 20. April 2026 ist der Anspruch nicht verjährt. (Die Sonderregel zur Reparatur aus dem neuen § 475e V gilt erst für Verträge ab dem 31.07.2026.)", "Ergebnis: b ist richtig."]}, "P6-vl7-16": {"k": "Nicht verjährt: Be", "w": ["Frage: Wann verjähren Ansprüche wegen fehlerhaft bereitgestellter Verkehrsdaten?", "Das Navi ist eine Ware mit digitalen Elementen, die dauerhaft bereitgestellt werden (§ 475c; Skript-Beispiel Verkehrsdaten). Die Elemente müssen während des ganzen Bereitstellungszeitraums mangelfrei sein – hier bis 31. Mai 2027. Fehlerhafte Daten seit März 2027 sind ein Mangel.", "Verjährung grundsätzlich 2 Jahre ab Ablieferung (§ 438 I Nr. 3) – würde den Anspruch abschneiden.", "§ 475e I: Bei dauerhafter Bereitstellung verjähren Ansprüche wegen eines Mangels an den digitalen Elementen nicht vor Ablauf von zwölf Monaten nach dem Ende des Bereitstellungszeitraums → nicht vor dem 31. Mai 2028.", "Ergebnis: e – im August 2027 nicht verjährt."]}, "P6-vl7-17": {"k": "K kann von H den A", "w": ["Frage: Wer muss für den Kompressorausfall nach drei Jahren einstehen?", "Gewährleistung gegen den Verkäufer E (§ 437): verjährt zwei Jahre nach Ablieferung (§ 438 I Nr. 3, II). Außerdem müsste der Mangel schon bei Gefahrübergang vorgelegen haben – Verschleiß nach drei Jahren fällt nicht darunter.", "Garantie (§ 443): besteht neben der Gewährleistung. H hat eine Haltbarkeitsgarantie gegeben (Kompressor hält fünf Jahre) – ein selbständiger Garantievertrag mit eigener Anspruchsgrundlage gegen H. Verschulden ist nicht erforderlich.", "Der Inhalt bestimmt sich nach der Garantieerklärung: Ausfall innerhalb von fünf Jahren → kostenloser Tausch.", "Ergebnis: a ist richtig."]}, "P6-vl7-18": {"k": "Beschaffenheitsgar", "w": ["Frage: Welche Garantie liegt vor, und was folgt daraus?", "Garantiearten (Skript VL 7): Haltbarkeitsgarantie = Einstehen für eine Beschaffenheit über einen bestimmten Zeitraum (z. B. 5 Jahre rostfrei). Beschaffenheitsgarantie = Einstehen für eine Soll-Beschaffenheit zum Zeitpunkt des Gefahrübergangs (Skript-Beispiele: Farbechtheit, Benzinverbrauch).", "„Höchstens 5,0 l“ betrifft den Zustand bei Übergabe → Beschaffenheitsgarantie. Der Wagen verbraucht schon bei Übergabe 6,2 l → Mangel (§ 434 II 1 Nr. 1).", "Folgen: Mängelrechte aus § 437; die Garantie besteht daneben (§ 443 I). Für Schadensersatz haftet A ohne Verschulden (§ 276 I 1); ein Haftungsausschluss wäre insoweit unwirksam (§ 444).", "Ergebnis: d ist richtig."]}, "P6-vl7-19": {"k": "Die Garantie ist t", "w": ["Frage: Macht eine Garantieerklärung, die gegen § 479 verstößt, die Garantie unwirksam?", "Beim Verbrauchsgüterkauf muss eine Garantieerklärung einfach und verständlich abgefasst sein und bestimmte Pflichtangaben enthalten, z. B. Hinweis auf die unentgeltlichen gesetzlichen Rechte, Name und Anschrift des Garantiegebers, Inhalt und Dauer (§ 479 I, II; Skript: „lesen!“).", "§ 479 III: Die Wirksamkeit der Garantieverpflichtung wird nicht dadurch berührt, dass eine dieser Anforderungen nicht erfüllt wird. Zweck: Der Verbraucher soll durch den Fehler des Garantiegebers nicht schlechter stehen.", "Der Motor fällt innerhalb der 3 Jahre aus → Anspruch aus der Garantie (§ 443). Die gesetzliche Gewährleistung (2 Jahre) wäre dagegen abgelaufen.", "Ergebnis: c ist richtig."]}, "P6-vl7-20": {"k": "H kann die 120 € f", "w": ["Frage: Kann H die Reparaturkosten von seinem Lieferanten zurückverlangen?", "Rückgriff des Verkäufers (§ 445a I): Der Verkäufer kann beim Verkauf einer neu hergestellten Sache von seinem Lieferanten Ersatz der Aufwendungen verlangen, die er im Verhältnis zum Käufer nach § 439 II, III (und § 475 IV) tragen musste, wenn der Mangel schon beim Übergang auf den Verkäufer vorhanden war – ohne Verschulden des Lieferanten.", "Skript VL 7: Die Regelungen des Rückgriffs sind auf neu hergestellte Sachen beschränkt.", "Smartphone: neu, Mangel lag schon bei L vor → 120 € aus § 445a I. Laptop: gebraucht → kein Rückgriff nach § 445a; H bleiben nur seine eigenen Mängelrechte aus dem Kauf mit L (§§ 437 ff.).", "Ergebnis: e ist richtig."]}, "P6-vl7-21": {"k": "Der Rücktritt ist ", "w": ["Frage: Musste S trotz der Arglist des N eine Frist zur Nacherfüllung setzen?", "Rücktritt: §§ 437 Nr. 2, 323 I. Mangel: Die tatsächliche Laufleistung weicht erheblich von dem ab, was angezeigt war (§ 434 III).", "Entbehrlichkeit außerhalb des Verbrauchsgüterkaufs: § 323 II, § 440. Nach § 440 S. 1 Var. 3 ist keine Frist nötig, wenn die Nacherfüllung dem Käufer unzumutbar ist. Nach dem BGH ist das bei arglistiger Täuschung durch den Verkäufer in der Regel der Fall.", "Zudem ist eine zu hohe Laufleistung gar nicht behebbar → Rücktritt ohne Frist auch über § 326 V. Der Mangel ist erheblich.", "Ergebnis: b – der Rücktritt ist wirksam (daneben wäre Anfechtung nach § 123 möglich)."]}, "P6-vl7-22": {"k": "V kann zurücktrete", "w": ["Zwei Fragen: (1) Kann V zurücktreten? (2) Muss E den Parkettschaden ersetzen?", "Mangel bei Gefahrübergang (Produktionsfehler, § 434). Zu (1): Rücktritt (§§ 437 Nr. 2, 323) ist verschuldensunabhängig; V hat E über den Mangel unterrichtet, die angemessene Frist ist abgelaufen → keine weitere Fristsetzung nötig (§ 475d I Nr. 1).", "Zu (2): Der Parkettschaden ist ein Mangelfolgeschaden → §§ 437 Nr. 3, 280 I (ohne Frist). Voraussetzung: E hat die Pflichtverletzung zu vertreten (§ 280 I 2). Eigenes Verschulden: Ein Händler muss originalverpackte Ware nicht auf versteckte Produktionsfehler untersuchen. Fremdes Verschulden: Der Hersteller ist nicht Erfüllungsgehilfe des Händlers (§ 278).", "Für den Parkettschaden kann V sich an den Hersteller halten (§ 1 ProdHaftG, § 823 I).", "Ergebnis: a ist richtig."]}, "P6-vl7-23": {"k": "Der Rücktritt wirk", "w": ["Frage: Kann K seinen Rücktritt zurücknehmen und stattdessen mindern?", "Rücktritt (§§ 437 Nr. 2, 323, 349): Voraussetzungen liegen vor (Mangel, erfolglose Frist, erheblich). Er wird durch einseitige, empfangsbedürftige Erklärung gegenüber dem Verkäufer ausgeübt (§ 349); formfrei, ohne Begründung.", "Wirkung: Mit Zugang (§ 130 I) wird das Leistungsverhältnis unwiderruflich in ein Rückabwicklungsverhältnis umgewandelt (§§ 346, 347; Skript VL 7).", "Ein einseitiger Widerruf oder Wechsel zur Minderung ist danach nicht mehr möglich; nur eine Vereinbarung mit V könnte den Vertrag wiederherstellen.", "Ergebnis: e ist richtig."]}, "P6-vl7-24": {"k": "D kann Schadensers", "w": ["Frage: Kann D die Maschine zurückgeben und Kaufpreis plus Mehrkosten verlangen?", "Schadensersatz statt der Leistung (§§ 437 Nr. 3, 280 I, III, 281): Mangel, erfolglose Frist, Vertretenmüssen (vermutet, § 280 I 2; H ahnte den Defekt).", "Großer Schadensersatz (statt der ganzen Leistung): nur bei erheblichem Mangel (§ 281 I 3) – ständige Papierstaus sind erheblich. Der Käufer gibt die Sache zurück (§ 281 V i. V. m. §§ 346–348) und verlangt den gesamten Schaden.", "Schaden nach der Differenzmethode: D hat 23.000 € für ein vergleichbares Gerät aufgewandt → H muss 20.000 € (Kaufpreis) + 3.000 € (Mehrkosten) zahlen, Zug um Zug gegen Rückgabe.", "Ergebnis: d ist richtig."]}, "P6-vl7-25": {"k": "Der Rücktritt ist ", "w": ["Frage: Kann U nach Ablauf von zwei Jahren noch wirksam zurücktreten?", "Rücktritt und Minderung sind Gestaltungsrechte und verjähren selbst nicht (nur Ansprüche verjähren, § 194 I). Das Skript nennt deshalb für § 438 nur Nacherfüllung (Nr. 1) und Schadens-/Aufwendungsersatz (Nr. 3).", "Aber § 438 IV 1 verweist für den Rücktritt auf § 218: Der Rücktritt ist unwirksam, wenn der Anspruch auf Leistung bzw. Nacherfüllung verjährt ist und der Schuldner sich darauf beruft (§ 218 I 1, 2).", "Nacherfüllungsanspruch: 2 Jahre ab Ablieferung (§ 438 I Nr. 3, II) → Ablauf 2. Mai 2025. Rücktritt am 15. Juli 2025; H beruft sich auf Verjährung → unwirksam. Kein Verbrauchsgüterkauf, also keine Ablaufhemmung nach § 475e.", "Ergebnis: c ist richtig."]}, "P6-vl7-26": {"k": "Die Beendigung ist", "w": ["Frage: Durfte V den Vertrag ohne vorherige Aufforderung beenden?", "Digitales Produkt (Software zum Download): Es gelten die §§ 327 ff., die als besonderes Gewährleistungsrecht dem Kaufrecht vorgehen (Skript VL 7).", "Bereitstellung (§ 327b): S muss das Produkt unverzüglich bereitstellen; die Beweislast dafür trägt S (§ 327b VI; im Skript als „§ 327 VI“ zitiert). Rechte bei unterbliebener Bereitstellung: § 327c I – der Verbraucher kann den Vertrag beenden, wenn der Unternehmer einer Aufforderung zur Bereitstellung nicht unverzüglich nachkommt.", "Die Aufforderung ist nur ausnahmsweise entbehrlich (§ 327c III, z. B. bei eindeutiger Verweigerung). Hier hat V S gar nicht aufgefordert.", "Ergebnis: f – V muss S erst zur Bereitstellung auffordern."]}, "P6-vl7-27": {"k": "S kann den Vertrag", "w": ["Frage: Welche Rechte hat S wegen der abstürzenden App?", "Die App ist ein digitales Produkt; die §§ 327 ff. gelten auch bei Abonnements und gehen dem Kaufrecht vor (Skript VL 7).", "Produktmangel (§ 327e): Die App erfüllt die subjektiven und objektiven Anforderungen nicht – sie stürzt bei jeder Übung ab. Bei dauerhafter Bereitstellung muss das Produkt während des ganzen Zeitraums mangelfrei sein.", "Rechte (§ 327i): Nacherfüllung (§ 327l); hat A nicht nacherfüllt, Vertragsbeendigung (§ 327m) oder Minderung (§ 327n); daneben Schadensersatz. Beweislast: § 327k – zeigt sich ein Mangel innerhalb eines Jahres, wird er vermutet; bei dauerhafter Bereitstellung gilt das für den Bereitstellungszeitraum.", "Ergebnis: b ist richtig."]}});
window.dispatchEvent(new Event('wpr-data'));
})();
